const api=(op,...args)=>window.biz.call(op,...args);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const date=s=>new Date(s).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
const icon=n=>'<span class="ico '+n+'" aria-hidden="true"></span>';
const state={folders:[],notes:[],note:null,folderId:null,expanded:new Set(),prefs:{},custom:[],info:{},view:'home',dirty:false,revision:0,saveTimer:null,saveQueue:Promise.resolve(),searchSeq:0,theme:'tactical',lastRange:null};
let toastTimer,prefTimer;
function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,error?9000:4200);}
function run(fn){return Promise.resolve().then(fn).catch(e=>{toast(e.message||String(e),true);console.error(e);});}
function savedStatus(message,error=false){$('#save-status').textContent=message;$('#data-status').classList.toggle('error',error);}
function placeStatus(){savedStatus('Salvo · '+state.info.directory);$('#data-status').title='Pasta de dados: '+state.info.directory;}
async function savePrefs(){clearTimeout(prefTimer);state.prefs.expanded=Array.from(state.expanded);state.prefs.theme=state.theme;await api('savePreferences',state.prefs);}
function soonPrefs(){clearTimeout(prefTimer);prefTimer=setTimeout(()=>run(savePrefs),500);}
function allThemes(){return [...BizThemes.themes,...BizThemes.universes,...state.custom];}
function themeById(id){return allThemes().find(t=>t.id===id)||BizThemes.themes.find(t=>t.id==='tactical');}
const patterns={
 lines:'repeating-linear-gradient(0deg,transparent 0 35px,var(--border) 35px 36px)',grid:'linear-gradient(var(--border) 1px,transparent 1px),linear-gradient(90deg,var(--border) 1px,transparent 1px)',diagonal:'repeating-linear-gradient(135deg,transparent 0 12px,var(--border) 12px 13px)',diamonds:'repeating-linear-gradient(45deg,transparent 0 35px,var(--border) 35px 36px),repeating-linear-gradient(-45deg,transparent 0 35px,var(--border) 35px 36px)',leather:'repeating-linear-gradient(90deg,transparent 0 3px,var(--border) 3px 4px)',petals:'radial-gradient(ellipse at 0% 0%,var(--secondary),transparent 35%),radial-gradient(ellipse at 100% 100%,var(--accent),transparent 30%)',clouds:'radial-gradient(ellipse at 20% 5%,var(--secondary),transparent 35%),radial-gradient(ellipse at 90% 20%,var(--accent),transparent 35%)',stars:'radial-gradient(circle,var(--secondary) 1px,transparent 1.5px)',footprints:'radial-gradient(ellipse at 10px 10px,var(--secondary) 2px,transparent 3px)',bubbles:'radial-gradient(circle,transparent 13px,var(--secondary) 14px,transparent 15px)',confetti:'radial-gradient(circle,var(--accent) 2px,transparent 3px)',leaves:'repeating-linear-gradient(125deg,transparent 0 65px,var(--secondary) 65px 67px,transparent 67px 130px)',blocks:'repeating-linear-gradient(0deg,transparent 0 40px,var(--border) 40px 43px),repeating-linear-gradient(90deg,transparent 0 40px,var(--border) 40px 43px)',scan:'repeating-linear-gradient(0deg,transparent 0 4px,var(--border) 4px 5px)',pixels:'repeating-linear-gradient(0deg,transparent 0 8px,var(--border) 8px 10px),repeating-linear-gradient(90deg,transparent 0 8px,var(--border) 8px 10px)',lace:'radial-gradient(circle,transparent 6px,var(--secondary) 7px,transparent 8px)',ruled:'repeating-linear-gradient(0deg,transparent 0 30px,var(--border) 30px 31px)',parchment:'radial-gradient(ellipse at 50% 50%,transparent 40%,var(--secondary) 100%)',bamboo:'repeating-linear-gradient(90deg,transparent 0 67px,var(--secondary) 67px 70px)'};
function universeAppearance(id){
 const saved=state.prefs.universeAppearance?.[id];
 const percent=(value,fallback)=>Number.isFinite(value)?Math.max(0,Math.min(100,Math.round(value))):fallback;
 return {wallpaper:percent(saved?.wallpaper,100),interface:percent(saved?.interface,0)};
}
function applyUniverseAppearance({wallpaper,interface:transparency}){
 const root=document.documentElement.style;
 root.setProperty('--wallpaper-veil',(100-wallpaper)+'%');
 // Limit the fill dilution so labels and icons stay legible over bright artwork.
 root.setProperty('--interface-fill',(100-transparency*.25)+'%');
 document.body.dataset.translucent=String(transparency>0);
}
function applyTheme(raw){let t;try{t=BizThemes.validate(raw);}catch{t=BizThemes.themes[3];}const r=document.documentElement;for(const k of ['bg','surface','sidebar','editor','text','muted','accent','ink','border','secondary'])r.style.setProperty('--'+k,t[k]);r.style.setProperty('--heading,t.heading',t.heading);r.style.setProperty('--heading',"'"+t.heading+"'");r.style.setProperty('--font',"'"+t.font+"'");r.style.setProperty('--font-size',t.fontSize+'px');r.style.setProperty('--radius',t.round);r.style.setProperty('--shadow',t.shadow==='none'?'none':t.shadow==='medium'?'0 5px 15px #0002':'0 3px 14px #0001');r.style.setProperty('--decoration',t.decoration);r.style.setProperty('--motif',patterns[t.pattern]||'none');const artwork=BizThemes.backgroundSource(t);r.style.setProperty('--custom-bg',artwork?'url("'+artwork+'")':'none');document.body.dataset.universe=String(t.visualUniverse);applyUniverseAppearance(universeAppearance(t.id));r.style.setProperty('--art-position',t.artPosition);r.style.setProperty('--art-focus',t.artFocus||t.artPosition+' center');r.style.setProperty('--editor-art-focus',t.artFocus||t.artPosition+' top');document.body.dataset.style=t.style;document.body.dataset.iconStyle=t.iconStyle;document.body.dataset.buttonStyle=t.buttonStyle;const style=document.getElementById('pattern-size')||Object.assign(document.createElement('style'),{id:'pattern-size'});style.textContent='.main::before{background-size:'+(['grid','stars','footprints','bubbles','confetti','lace'].includes(t.pattern)?(t.pattern==='grid'?'45px 45px':'50px 50px'):'auto')+'}';if(!style.parentNode)document.head.appendChild(style);}
function sanitize(html){const doc=document.createElement('template');doc.innerHTML=String(html||'');const allowed=new Set('P BR DIV SPAN B STRONG I EM U S STRIKE UL OL LI H1 H2 H3 H4 BLOCKQUOTE PRE CODE A TABLE THEAD TBODY TR TH TD IMG HR MARK FONT'.split(' '));for(const el of Array.from(doc.content.querySelectorAll('*'))){if(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH','FORM','INPUT','BUTTON','LINK','META'].includes(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}for(const a of Array.from(el.attributes)){const key=a.name.toLowerCase();let keep=false;if(key==='class') {const classes=el.className.split(/\s+/).filter(s=>['bizu','pegadinha','callout-label','task-check'].includes(s));el.className=classes.join(' ');keep=true;}else if(key==='style'){const out=[];for(const name of ['color','background-color','text-align','font-weight','font-style','text-decoration','font-size','font-family','white-space','width','height','vertical-align','margin-left']){const v=el.style.getPropertyValue(name);if(v&&!/url|expression|javascript|var\(/i.test(v)&&/^[\w\s#(),.%'"-]+$/.test(v))out.push(name+':'+v);}el.setAttribute('style',out.join(';'));keep=true;}else if(el.tagName==='IMG'&&key==='src')keep=/^(tv-attachment:\/\/[a-f0-9-]+\.(png|jpe?g|gif|webp|bmp)\/?|data:image\/(png|jpeg|gif|webp|bmp);base64,[a-zA-Z0-9+/=]+)$/i.test(a.value);else if(el.tagName==='IMG'&&['alt','width','height'].includes(key))keep=key==='alt'||/^\d{1,4}$/.test(a.value);else if(el.tagName==='A'&&key==='href')keep=/^(https?:|mailto:)/i.test(a.value);else if(el.tagName==='FONT'&&key==='color')keep=/^#[a-f0-9]{3,8}$/i.test(a.value);else if(['TD','TH'].includes(el.tagName)&&['colspan','rowspan'].includes(key))keep=/^[1-9]\d?$/.test(a.value);if(!keep)el.removeAttribute(a.name);}if(el.tagName==='IMG'&&!el.getAttribute('src'))el.remove();}return doc.innerHTML;}
function cleanEditorHtml(){const clone=$('#editor').cloneNode(true);for(const mark of clone.querySelectorAll('.found-text'))mark.replaceWith(...mark.childNodes);return sanitize(clone.innerHTML);}
let wordTimer;
function countWords(){const text=$('#editor')?.innerText||'';$('#word-count').textContent=state.note?(text.trim()?text.trim().split(/\s+/).length:0)+' palavras':'';}
function markDirty(){state.dirty=true;state.revision++;savedStatus('Alterações pendentes…');clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>run(flush),550);clearTimeout(wordTimer);wordTimer=setTimeout(countWords,180);}
async function flush(){clearTimeout(state.saveTimer);if(!state.note||!state.dirty||!$('#editor'))return state.saveQueue;const id=state.note.id,revision=state.revision;const patch={title:$('#note-title').value,contentHtml:cleanEditorHtml(),tags:$('#note-tags').value.split(',').map(s=>s.trim()).filter(Boolean)};state.saveQueue=state.saveQueue.catch(()=>{}).then(async()=>{try{savedStatus('Salvando…');const n=await api('updateNote',id,patch);if(state.note?.id===id){state.note=n;if(state.revision===revision){state.dirty=false;placeStatus();}}const list=state.notes.find(n=>n.id===id);if(list){list.title=n.title;list.updatedAt=n.updatedAt;}updateTreeNote(id,n.title);}catch(e){savedStatus('Falha ao salvar — mantenha o programa aberto',true);state.dirty=true;throw e;}});return state.saveQueue;}
function updateTreeNote(id,title){const label=$('[data-note-id="'+id+'"] .label');if(label){label.textContent=title;label.parentElement.title=title;}}
function folderPath(id){return cachedFolderPath(id);}
function revealFolder(id){for(const folder of folderChain(id))state.expanded.add(folder.id);}
async function refresh(){[state.folders,state.notes]=await Promise.all([api('listFolders'),api('listNotes',{limit:100000})]);indexFolders();renderTree();renderConsultFolders();$('#folder-total').textContent=state.folders.length+' pastas';}
function renderConsultFolders(){const select=$('#consult-folder'),value=select.value;select.innerHTML='<option value="">Toda a biblioteca</option>'+state.folders.filter(f=>f.parentId==null).map(f=>'<option value="'+f.id+'">'+esc(f.name)+'</option>').join('');select.value=value;}
function orderCourseNotes(folderId, notes){
 const [language,level]=folderChain(folderId);
 if(level?.id===folderId&&['inglês','espanhol','francês','italiano'].includes(language?.name.toLocaleLowerCase('pt-BR'))&&
   ['iniciante','intermediário','avançado','aumentar vocabulário'].includes(level.name.toLocaleLowerCase('pt-BR')))
   return notes.toSorted((a,b)=>a.title.localeCompare(b.title,'pt-BR',{numeric:true}));
 return notes;
}
function renderTree(){const tree=$('#tree'),scroll=tree.scrollTop;const active=tree.contains(document.activeElement)?document.activeElement.closest('.tree-row'):null;const focusKey=active?.dataset.folderId?'folderId':'noteId';const focusId=active?.dataset[focusKey];const q=normalize($('#tree-search').value);const childMap=new Map(),noteMap=new Map(),matched=new Set();for(const f of state.folders){if(!childMap.has(f.parentId))childMap.set(f.parentId,[]);childMap.get(f.parentId).push(f);}for(const n of state.notes){if(!noteMap.has(n.folderId))noteMap.set(n.folderId,[]);noteMap.get(n.folderId).push(n);}const addAncestors=id=>{let i=id,g=0;while(i!=null&&g++<100){matched.add(i);i=folderIndex.get(i)?.parentId;}};if(q){for(const f of state.folders)if(normalize(f.name).includes(q))addAncestors(f.id);for(const n of state.notes)if(normalize(n.title).includes(q))addAncestors(n.folderId);}
 let html='';
 function notes(parent,depth,force=false){for(const n of orderCourseNotes(parent,noteMap.get(parent)||[])){if(q&&!force&&!normalize(n.title).includes(q))continue;html+='<div role="treeitem" tabindex="0" draggable="true" class="tree-row note-row '+(state.note?.id===n.id?'selected':'')+'" data-note-id="'+n.id+'" style="padding-left:'+(Math.min(depth,12)*12+7)+'px" title="'+esc(n.title)+'">'+icon('note')+'<span class="label">'+esc(n.title)+'</span><button class="tree-menu" aria-label="Opções da anotação">'+icon('more')+'</button></div>';}}
 function folders(parent,depth,parentMatched=false){if(depth>50)return;for(const f of childMap.get(parent)||[]){if(q&&!parentMatched&&!matched.has(f.id))continue;const selfMatched=q&&normalize(f.name).includes(q),open=q||state.expanded.has(f.id),children=(childMap.get(f.id)||[]).length+(noteMap.get(f.id)||[]).length;html+='<div role="treeitem" tabindex="0" aria-expanded="'+!!open+'" draggable="true" class="tree-row folder-row '+(!state.note&&state.folderId===f.id?'selected':'')+'" data-folder-id="'+f.id+'" style="padding-left:'+(Math.min(depth,12)*12)+'px" title="'+esc(folderPath(f.id))+'"><button class="tree-toggle" aria-label="'+(open?'Recolher':'Expandir')+' '+esc(f.name)+'">'+icon(open?'down':'chevron')+'</button>'+icon(open?'folder-open':'folder')+'<span class="label">'+esc(f.name)+'</span>'+(children?'<span class="tree-count">'+children+'</span>':'')+'<button class="tree-menu" aria-label="Opções da pasta">'+icon('more')+'</button></div>';if(open){folders(f.id,depth+1,parentMatched||selfMatched);notes(f.id,depth+1,parentMatched||selfMatched);}}}
 folders(null,0);if((noteMap.get(null)||[]).length){html+='<div class="tree-tools">SEM PASTA</div>';notes(null,0);}tree.innerHTML=html||'<div class="empty compact"><p>Nenhum item encontrado.</p></div>';tree.scrollTop=scroll;
 const rows=Array.from(tree.querySelectorAll('.tree-row'));
 const current=rows.find(row=>focusId&&row.dataset[focusKey]===focusId)||rows.find(row=>row.classList.contains('selected'))||rows[0];
 function treeTabStop(row){for(const item of rows)item.tabIndex=item===row?0:-1;}
 treeTabStop(current);if(active)current?.focus({preventScroll:true});
 for(const row of rows){row.onclick=e=>run(async()=>{if(e.target.closest('.tree-menu')){await flush();if(row.dataset.folderId)await folderMenu(Number(row.dataset.folderId));else await noteMenu(Number(row.dataset.noteId));return;}if(row.dataset.folderId){const id=Number(row.dataset.folderId);if(e.target.closest('.tree-toggle')){state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);renderTree();soonPrefs();}else await showFolder(id);}else await openNote(Number(row.dataset.noteId));});row.onfocus=()=>treeTabStop(row);for(const button of row.querySelectorAll('button'))button.tabIndex=-1;row.onkeydown=e=>{if(e.target!==row)return;const index=rows.indexOf(row);const next=e.key==='ArrowDown'?rows[index+1]:e.key==='ArrowUp'?rows[index-1]:e.key==='Home'?rows[0]:e.key==='End'?rows.at(-1):null;if(next){e.preventDefault();next.focus();return;}if(e.key==='F2'||(e.shiftKey&&e.key==='F10')){e.preventDefault();row.querySelector('.tree-menu')?.click();return;}if(e.key==='Enter'||e.key===' '){e.preventDefault();row.click();}if(row.dataset.folderId&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();const id=Number(row.dataset.folderId);e.key==='ArrowRight'?state.expanded.add(id):state.expanded.delete(id);renderTree();soonPrefs();}};row.oncontextmenu=e=>{e.preventDefault();run(async()=>{await flush();if(row.dataset.folderId)await folderMenu(Number(row.dataset.folderId));else await noteMenu(Number(row.dataset.noteId));});};row.ondragstart=e=>{e.dataTransfer.setData('application/x-bizuteca',JSON.stringify({type:row.dataset.folderId?'folder':'note',id:Number(row.dataset.folderId||row.dataset.noteId)}));};if(row.dataset.folderId){row.ondragover=e=>{if(e.dataTransfer.types.includes('application/x-bizuteca')){e.preventDefault();row.classList.add('drag-over');}};row.ondragleave=()=>row.classList.remove('drag-over');row.ondrop=e=>{e.preventDefault();row.classList.remove('drag-over');run(async()=>{await flush();const item=JSON.parse(e.dataTransfer.getData('application/x-bizuteca'));await api(item.type==='folder'?'moveFolder':'moveNote',item.id,Number(row.dataset.folderId));state.expanded.add(Number(row.dataset.folderId));await refresh();if(state.note)await openNote(state.note.id);toast('Item movido.');});};}}
}
function setView(view){if(view!==state.view&&$('.preview-banner')){applyTheme(themeById(state.theme));$('.preview-banner').remove();}rememberView(view);state.view=view;document.body.dataset.view=view;for(const b of $$('.side-nav button'))b.classList.toggle('active',b.dataset.view===view);$('#word-count').textContent='';}
function intro(eyebrow,title,description=''){return '<div class="page-intro"><div><div class="eyebrow">'+esc(eyebrow)+'</div><h1>'+esc(title)+'</h1><p>'+esc(description)+'</p></div></div>';}
function noteCards(notes){return notes.length?'<div class="notes-list">'+notes.map(n=>'<button class="note-card" data-open-note="'+n.id+'"><span><strong>'+esc(n.title)+'</strong><small>'+esc(folderPath(n.folderId)||'Sem pasta')+'</small></span><span><small>'+date(n.updatedAt)+'</small> '+icon(n.favorite?'star-filled':'note')+'</span></button>').join('')+'</div>':'<div class="empty">'+icon('note')+'<p>Seu caderno está pronto para receber conteúdo.</p><small>Crie uma anotação ou importe seus materiais.</small></div>';}
function wireNoteCards(container=$('#main')){for(const b of container.querySelectorAll('[data-open-note]'))b.onclick=()=>run(()=>openNote(Number(b.dataset.openNote)));}
async function flushStable(){do{await flush();}while(state.note&&state.dirty&&$('#editor'));}
async function leaveEditor(){await flushStable();$('#workspace').classList.remove('focus-writing');state.note=null;state.dirty=false;state.lastRange=null;}
async function home(view='home'){await leaveEditor();state.folderId=null;setView(view);await refresh();const favorite=view==='favorites',notes=favorite?state.notes.filter(n=>n.favorite):state.notes.slice(0,30);let html=intro(favorite?'SEUS DESTAQUES':'SEU CADERNO DE ESTUDOS',favorite?'Favoritos':view==='recent'?'Anotações recentes':'Seu conhecimento, no seu ritmo.',favorite?'Resumos que você marcou para encontrar mais rápido.':'Resumos, anotações e bizus organizados por matéria.');if(view==='home')html+='<section id="next-event" class="next-event" aria-live="polite"></section><section class="welcome-box"><h2>Um lugar para guardar o que você aprende.</h2><p>Escolha uma matéria na biblioteca, escreva seus resumos e encontre seu material ao consultar uma questão.</p><div class="button-row"><button id="welcome-create" class="primary">'+icon('plus')+' Criar anotação</button><button id="welcome-consult" class="outline">'+icon('consult')+' Encontrar no meu caderno</button></div></section>';if(view==='home'){
 const roots=state.folders.filter(f=>f.parentId==null).toSorted((a,b)=>a.name.localeCompare(b.name,'pt-BR',{numeric:true}));
 html+='<section id="home-folders"><div class="section-heading"><h2>Pastas-mãe</h2></div><p class="help">Escolha uma pasta para acessar suas subpastas e anotações.</p>'+(roots.length?'<div class="folder-grid">'+roots.map(f=>'<button class="folder-card" data-open-folder="'+f.id+'">'+icon('folder')+esc(f.name)+'</button>').join('')+'</div>':'<div class="empty"><p>Nenhuma pasta criada. Use o botão Pasta para organizar seu caderno.</p></div>')+'</section>';
 const loose=state.notes.filter(n=>n.folderId==null);
 if(loose.length)html+='<div class="section-heading"><h2>Anotações sem pasta</h2></div>'+noteCards(loose);
 }else html+='<div class="section-heading"><h2>'+(favorite?'Anotações favoritas':'Anotações recentes')+'</h2></div>'+noteCards(notes);if(favorite){const folders=state.folders.filter(f=>f.favorite);if(folders.length)html+='<div class="section-heading"><h2>Pastas favoritas</h2></div><div class="folder-grid">'+folders.map(f=>'<button class="folder-card" data-open-folder="'+f.id+'">'+icon('folder')+esc(f.name)+'</button>').join('')+'</div>';}$('#main').innerHTML=html;if(view==='home')await nextEventCard();wireNoteCards();if($('#welcome-create'))$('#welcome-create').onclick=()=>run(newNote);if($('#welcome-consult'))$('#welcome-consult').onclick=()=>toggleConsult(true);for(const b of $$('[data-open-folder]'))b.onclick=()=>run(()=>showFolder(Number(b.dataset.openFolder)));renderTree();}
async function showFolder(id){await leaveEditor();state.folderId=id;state.expanded.add(id);setView('folder');renderTree();soonPrefs();const f=state.folders.find(f=>f.id===id);if(!f)return home();const children=state.folders.filter(f=>f.parentId===id),notes=orderCourseNotes(id,state.notes.filter(n=>n.folderId===id));$('#main').innerHTML=breadcrumbs(id)+intro('BIBLIOTECA',f.name)+'<div class="button-row"><button id="folder-note" class="primary">'+icon('plus')+' Nova anotação aqui</button><button id="folder-sub" class="outline">'+icon('folder')+' Subpasta</button><button id="folder-options" class="outline">'+icon('more')+' Opções</button></div>'+(children.length?'<div class="section-heading"><h2>Subpastas</h2></div><div class="folder-grid">'+children.map(f=>'<button class="folder-card" data-open-folder="'+f.id+'">'+icon('folder')+esc(f.name)+'</button>').join('')+'</div>':'')+'<div class="section-heading"><h2>Anotações desta pasta</h2></div>'+noteCards(notes);wireNoteCards();for(const b of $$('[data-open-folder]'))b.onclick=()=>run(()=>showFolder(Number(b.dataset.openFolder)));$('#folder-note').onclick=()=>run(()=>newNote(id));$('#folder-sub').onclick=()=>run(()=>newFolder(id));$('#folder-options').onclick=()=>run(()=>folderMenu(id));}
function openDialog(title,body,buttons=[{id:'cancel',text:'Cancelar'},{id:'ok',text:'Confirmar',primary:true}]){return new Promise(resolve=>{const dialog=$('#dialog');$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;wireFolderPickers(dialog);$('#dialog-actions').innerHTML='';let settled=false;function finish(id){if(settled)return;if(buttons.some(b=>b.id===id&&b.primary)){const invalid=Array.from(dialog.querySelectorAll('input,textarea,select')).find(el=>!el.checkValidity());if(invalid){invalid.reportValidity();return;}}settled=true;const values={};for(const el of dialog.querySelectorAll('[name]'))values[el.name]=el.type==='checkbox'?el.checked:el.value;dialog.close();dialog.oncancel=null;resolve({id,values});}$('#dialog-close').onclick=()=>finish('cancel');dialog.oncancel=e=>{e.preventDefault();finish('cancel');};for(const b of buttons){const el=document.createElement('button');el.textContent=b.text;el.className=b.primary?'primary':b.danger?'danger':'outline';el.onclick=()=>finish(b.id);$('#dialog-actions').appendChild(el);}dialog.showModal();const first=dialog.querySelector('[autofocus]')||dialog.querySelector('input,select,textarea');first?.focus();dialog.onkeydown=e=>{if(e.key==='Enter'&&!['TEXTAREA','BUTTON'].includes(e.target.tagName)&&!e.target.closest('[data-folder-picker]')&&!e.ctrlKey){const ok=buttons.find(b=>b.primary);if(ok){e.preventDefault();finish(ok.id);}}};});}
async function confirmAction(title,message){return (await openDialog(title,'<p class="form-message">'+esc(message)+'</p>',[{id:'cancel',text:'Cancelar'},{id:'ok',text:'Confirmar',danger:true}])).id==='ok';}
async function newFolder(parent=null){await flush();const r=await openDialog('Nova pasta','<label class="field">Nome<input name="name" autofocus maxlength="220" placeholder="Ex.: Concordância verbal"></label>'+folderPicker('parent',parent));if(r.id!=='ok')return;if(!r.values.name.trim()){toast('Informe o nome da pasta.',true);return;}const id=await api('createFolder',{name:r.values.name,parentId:r.values.parent?Number(r.values.parent):null});revealFolder(id);await refresh();await showFolder(id);}
async function newNote(folder=state.folderId){await flush();const id=await api('createNote',{title:'Nova anotação',folderId:typeof folder==='number'?folder:null});await refresh();await openNote(id);$('#note-title').focus();$('#note-title').select();}
async function folderMenu(id){const f=state.folders.find(f=>f.id===id);if(!f)return;const r=await openDialog(f.name,'<div class="menu-list"><p class="help">'+esc(folderPath(id))+'</p></div>',[{id:'new',text:'Nova anotação',primary:true},{id:'sub',text:'Subpasta'},{id:'edit',text:'Gerenciar'},{id:'cancel',text:'Fechar'}]);if(r.id==='new')return newNote(id);if(r.id==='sub')return newFolder(id);if(r.id!=='edit')return;const e=await openDialog('Gerenciar pasta','<label class="field">Nome<input name="name" value="'+esc(f.name)+'" maxlength="220"></label>'+folderPicker('parent',f.parentId,[id])+'<label class="field inline"><input name="favorite" type="checkbox" '+(f.favorite?'checked':'')+'> Favorita</label><p class="help">Mover uma pasta também move suas subpastas e anotações. Ciclos são bloqueados.</p>',[{id:'delete',text:'Mover para lixeira',danger:true},{id:'cancel',text:'Cancelar'},{id:'ok',text:'Salvar',primary:true}]);if(e.id==='delete'){if(await confirmAction('Mover pasta para lixeira?','As subpastas e anotações também irão para a lixeira e poderão ser restauradas.')){await api('deleteFolder',id);await home();}}else if(e.id==='ok'){const parent=e.values.parent?Number(e.values.parent):null;if(parent!==f.parentId)await api('moveFolder',id,parent);await api('renameFolder',id,e.values.name);await api('setFolderFavorite',id,e.values.favorite);await refresh();await showFolder(id);}}
async function noteMenu(id){const n=await api('getNote',id);if(!n)return;const r=await openDialog('Opções da anotação','<p class="form-message">'+esc(n.title)+'</p>',[{id:'move',text:'Mover'},{id:'duplicate',text:'Duplicar'},{id:'delete',text:'Lixeira',danger:true},{id:'cancel',text:'Fechar'}]);if(r.id==='move'){const f=await openDialog('Mover anotação',folderPicker('folder',n.folderId));if(f.id==='ok'){await api('moveNote',id,f.values.folder?Number(f.values.folder):null);await refresh();await openNote(id);}}else if(r.id==='duplicate'){const dup=await api('duplicateNote',id);await refresh();await openNote(dup);}else if(r.id==='delete'&&await confirmAction('Mover anotação para lixeira?','Você poderá restaurá-la depois.')){await api('deleteNote',id);await home();}}
function selectionSave(){const sel=getSelection();if(sel.rangeCount&&$('#editor')?.contains(sel.anchorNode))state.lastRange=sel.getRangeAt(0).cloneRange();}
function selectionRestore(){const editor=$('#editor');if(!editor)return;editor.focus();if(state.lastRange&&editor.contains(state.lastRange.commonAncestorContainer)){const s=getSelection();s.removeAllRanges();s.addRange(state.lastRange);} }
function insertHtml(html){selectionRestore();document.execCommand('insertHTML',false,sanitize(html));selectionSave();markDirty();}
function format(command,value=null){selectionRestore();document.execCommand(command,false,value);selectionSave();markDirty();}
async function openNote(id,terms=[]){await flushStable();$('#workspace').classList.remove('focus-writing');const n=await api('getNote',id);if(!n||n.deletedAt){toast('Esta anotação não está disponível.',true);return;}state.note=n;state.folderId=n.folderId;state.dirty=false;state.lastRange=null;state.prefs.lastNote=id;soonPrefs();setView('editor');revealFolder(n.folderId);renderTree();$('#main').innerHTML=breadcrumbs(n.folderId)+'<div class="editor-heading"><div class="title-wrap"><input id="note-title" class="note-title" aria-label="Título da anotação" maxlength="500" value="'+esc(n.title)+'"><div class="note-meta">Editado em '+date(n.updatedAt)+'</div></div><button id="favorite-note" class="icon-button favorite-button '+(n.favorite?'is-favorite':'')+'" title="'+(n.favorite?'Remover dos favoritos':'Marcar como favorita')+'" aria-label="Favoritar anotação">'+icon(n.favorite?'star-filled':'star')+'</button><button id="note-options" class="icon-button" title="Opções da anotação" aria-label="Opções da anotação">'+icon('more')+'</button></div><div class="editor-toolbar" aria-label="Formatação"><button data-command="undo" title="Desfazer">'+icon('undo')+'</button><button data-command="redo" title="Refazer">'+icon('redo')+'</button><span class="toolbar-divider"></span><select id="text-style" aria-label="Estilo do texto"><option value="p">Texto</option><option value="h2">Título</option><option value="h3">Subtítulo</option><option value="blockquote">Citação</option></select><button data-command="bold" title="Negrito (Ctrl B)"><b>B</b></button><button data-command="italic" title="Itálico (Ctrl I)"><i>I</i></button><button data-command="underline" title="Sublinhado (Ctrl U)"><u>U</u></button><label title="Cor do texto">A<input id="text-color" type="color" value="#5ce66a" aria-label="Cor do texto"></label><label title="Marca-texto">'+icon('highlight')+'<input id="highlight-color" type="color" value="#e6c350" aria-label="Marca-texto"></label><span class="toolbar-divider"></span><button data-command="insertUnorderedList" title="Lista com marcadores">'+icon('menu')+'</button><button data-command="insertOrderedList" title="Lista numerada">1.</button><button id="insert-table" title="Inserir tabela">'+icon('table')+'</button><button id="insert-bizu" title="Inserir bloco de bizu">Bizu</button><button id="insert-trap" title="Inserir pegadinha">Pegadinha</button><button id="insert-image" title="Inserir imagem">'+icon('attach')+'</button><button data-command="removeFormat" title="Limpar formatação">Tx</button></div><article id="editor" class="editor" contenteditable="true" role="textbox" aria-label="Conteúdo da anotação" aria-multiline="true" data-placeholder="Escreva seu resumo, cole uma anotação ou registre um bizu…"></article><div class="note-bottom"><button id="attach-file" class="outline small">'+icon('attach')+' Anexar material</button><button id="versions" class="outline small">'+icon('clock')+' Versões</button><button id="export-note" class="outline small">'+icon('export')+' Exportar</button></div><div id="attachments" class="note-attachments"></div><label class="field">Etiquetas <span class="help">Opcionais, separadas por vírgula</span><input id="note-tags" placeholder="Ex.: revisão, importante" value="'+esc(n.tags.join(', '))+'"></label>';
 const editor=$('#editor');editor.innerHTML=sanitize(n.contentHtml);if(terms.length)highlightEditor(terms);editor.oninput=markDirty;editor.onkeyup=selectionSave;editor.onmouseup=selectionSave;editor.onpaste=onPaste;editor.onclick=e=>{if(e.target.closest('a'))e.preventDefault();};$('#note-title').oninput=markDirty;$('#note-tags').oninput=markDirty;
 for(const b of $$('.editor-toolbar button'))b.onmousedown=e=>e.preventDefault();for(const b of $$('[data-command]'))b.onclick=()=>format(b.dataset.command);$('#text-style').onchange=e=>format('formatBlock',e.target.value);for(const s of ['#text-style','#text-color','#highlight-color'])$(s).onmousedown=selectionSave;$('#text-color').oninput=e=>format('foreColor',e.target.value);$('#highlight-color').oninput=e=>format('hiliteColor',e.target.value);
 $('#insert-bizu').onclick=()=>{const text=getSelection().toString();insertHtml('<div class="bizu"><span class="callout-label">BIZU</span><p>'+esc(text||'Escreva seu bizu aqui.')+'</p></div><p><br></p>');};$('#insert-trap').onclick=()=>{const text=getSelection().toString();insertHtml('<div class="pegadinha"><span class="callout-label">PEGADINHA</span><p>'+esc(text||'Registre aqui o detalhe que merece atenção.')+'</p></div><p><br></p>');};$('#insert-table').onclick=()=>run(async()=>{selectionSave();const r=await openDialog('Inserir tabela','<div class="form-grid"><label class="field">Linhas<input name="rows" type="number" min="1" max="20" value="3"></label><label class="field">Colunas<input name="cols" type="number" min="1" max="10" value="2"></label></div>');if(r.id==='ok'){const rows=Math.max(1,Math.min(20,Number(r.values.rows)||3)),cols=Math.max(1,Math.min(10,Number(r.values.cols)||2));insertHtml('<table><tbody>'+Array.from({length:rows},()=>'<tr>'+Array.from({length:cols},()=>'<td><br></td>').join('')+'</tr>').join('')+'</tbody></table><p><br></p>');}});
 $('#insert-image').onclick=()=>{selectionSave();const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp,image/gif';input.onchange=()=>run(async()=>{const file=input.files[0];if(file)await insertImage(file);});input.click();};$('#attach-file').onclick=()=>run(async()=>{await flush();const result=await api('attach',n.id);if(result){await showFiles();toast(result+' anexo(s) adicionado(s).');}});$('#favorite-note').onclick=()=>run(async()=>{await flush();await api('setNoteFavorite',n.id,!state.note.favorite);state.note.favorite=!state.note.favorite;const saved=state.notes.find(x=>x.id===n.id);if(saved)saved.favorite=state.note.favorite;$('#favorite-note').classList.toggle('is-favorite',state.note.favorite);$('#favorite-note').innerHTML=icon(state.note.favorite?'star-filled':'star');});$('#note-options').onclick=()=>run(async()=>{await flush();await noteMenu(n.id);});$('#versions').onclick=()=>run(()=>showVersions(n.id));$('#export-note').onclick=()=>run(async()=>{await flush();const r=await openDialog('Exportar anotação','<p class="form-message">Escolha o formato para leitura, impressão ou compartilhamento.</p>',[{id:'pdf',text:'PDF',primary:true},{id:'html',text:'HTML'},{id:'txt',text:'Texto'},{id:'cancel',text:'Cancelar'}]);if(r.id!=='cancel'){const file=await api('exportMaterial',r.id,[n.id]);if(file)toast('Material exportado.');}});enhanceEditor(editor);await showFiles();countWords();placeStatus();$('#main').scrollTop=0;
}
async function insertImage(file){const editor=$('#editor');if(!file||!editor)return;if(file.size>20*1024*1024)throw Error('A imagem pode ter até 20 MB.');const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=rej;r.readAsDataURL(file);});if(editor!==$('#editor'))return;const url=await api('saveImage',{data,mime:file.type});if(editor!==$('#editor'))return;insertHtml('<img src="'+url+'" alt="Imagem da anotação"><p><br></p>');}
async function onPaste(e){e.preventDefault();selectionSave();if(Number(e.currentTarget.dataset.plainPaste)>Date.now()){delete e.currentTarget.dataset.plainPaste;insertHtml(esc(e.clipboardData.getData('text/plain')).replace(/\r?\n/g,'<br>'));return;}const image=Array.from(e.clipboardData.items).find(i=>i.type.startsWith('image/'));if(image){await run(()=>insertImage(image.getAsFile()));return;}const html=e.clipboardData.getData('text/html');const text=e.clipboardData.getData('text/plain');insertHtml(html||esc(text).replace(/\r?\n/g,'<br>'));}
function highlightEditor(terms,scroll=true){const editor=$('#editor');const words=terms.map(normalize).filter(t=>t.length>=3);if(!words.length)return;const walker=document.createTreeWalker(editor,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);let first=null;for(const node of nodes){const text=node.textContent,parts=text.split(/(\s+)/),frag=document.createDocumentFragment();for(const p of parts){if(words.some(w=>normalize(p).includes(w))){const mark=document.createElement('mark');mark.className='found-text';mark.textContent=p;frag.append(mark);if(!first)first=mark;}else frag.append(document.createTextNode(p));}node.replaceWith(frag);}if(first&&scroll)setTimeout(()=>first.scrollIntoView({block:'center'}),70);}
async function showFiles(){if(!state.note||!$('#attachments'))return;const list=await api('files',state.note.id);$('#attachments').innerHTML=list.map(f=>'<div class="attachment"><button data-file="'+f.id+'" title="Abrir '+esc(f.name)+'">'+icon('attach')+esc(f.name)+'</button><button class="remove" data-remove-file="'+f.id+'" aria-label="Remover anexo">'+icon('close')+'</button></div>').join('');for(const b of $$('[data-file]'))b.onclick=()=>run(()=>api('openFile',Number(b.dataset.file)));for(const b of $$('[data-remove-file]'))b.onclick=()=>run(async()=>{if(await confirmAction('Remover vínculo do anexo?','O arquivo deixa de aparecer nesta anotação. A cópia no armazenamento é preservada para segurança.')){await api('deleteFile',Number(b.dataset.removeFile));await showFiles();}});}
async function showVersions(id){await flush();const versions=await api('listVersions',id);const r=await openDialog('Versões da anotação',versions.length?'<label class="field">Versão<select name="version">'+versions.map(v=>'<option value="'+v.id+'">'+date(v.savedAt)+' — '+esc(v.title)+'</option>').join('')+'</select></label><p class="help">Ao restaurar, a versão atual também é guardada.</p>':'<p class="form-message">As versões anteriores aparecem aqui depois que você edita e salva a anotação.</p>',versions.length?[{id:'preview',text:'Ver versão',primary:true},{id:'cancel',text:'Fechar'}]:[{id:'cancel',text:'Fechar'}]);if(r.id==='preview'){const v=await api('getVersion',Number(r.values.version));const restore=await openDialog('Versão de '+date(v.savedAt),'<h3>'+esc(v.title)+'</h3><div class="version-preview">'+sanitize(v.contentHtml)+'</div>',[{id:'cancel',text:'Cancelar'},{id:'restore',text:'Restaurar esta versão',primary:true}]);if(restore.id==='restore'){await api('restoreVersion',v.id);await refresh();await openNote(id);toast('Versão restaurada.');}}}
async function trash(){await leaveEditor();setView('trash');renderTree();const t=await api('listTrash');const list=[...t.folders.map(f=>({...f,type:'folder',title:f.name})),...t.notes.map(n=>({...n,type:'note'}))];$('#main').innerHTML=intro('RECUPERAÇÃO','Lixeira','Itens excluídos podem ser restaurados. Nada é apagado automaticamente.')+(list.length?'<div class="button-row"><button id="empty-trash" class="danger small">Esvaziar lixeira</button></div>'+list.map(n=>'<div class="trash-row"><span class="ico '+(n.type==='folder'?'folder':'note')+'"></span><span class="trash-label">'+esc(n.title)+'<small>'+date(n.deletedAt)+'</small></span><button class="outline small" data-restore="'+n.type+':'+n.id+'">Restaurar</button></div>').join(''):'<div class="empty">'+icon('trash')+'<p>A lixeira está vazia.</p></div>');for(const b of $$('[data-restore]'))b.onclick=()=>run(async()=>{const [type,id]=b.dataset.restore.split(':');await api(type==='folder'?'restoreFolder':'restoreNote',Number(id));await refresh();await trash();toast('Item restaurado.');});if($('#empty-trash'))$('#empty-trash').onclick=()=>run(async()=>{if(await confirmAction('Esvaziar lixeira?','Os itens serão excluídos definitivamente. Uma cópia de segurança será criada antes.')){await api('emptyTrash');await refresh();await trash();toast('Lixeira esvaziada. Backup de segurança criado.');}});}
function snippetHtml(text,terms=[]){const clean=String(text||'').replace(/\[\[|\]\]/g,'');if(!terms.length)return esc(clean);const candidates=terms.filter(t=>String(t).length>2).sort((a,b)=>b.length-a.length).map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));if(!candidates.length)return esc(clean);const rx=new RegExp('('+candidates.join('|')+')','gi');return clean.split(rx).map((part,i)=>i%2?'<mark>'+esc(part)+'</mark>':esc(part)).join('');}
function toggleConsult(open){const panel=$('#workspace');const show=open??panel.classList.contains('hide-consult');panel.classList.toggle('hide-consult',!show);setSidebarWidth();state.prefs.consultOpen=show;soonPrefs();if(show)$('#question').focus();}
async function doConsult(){await flush();const text=$('#question').value.trim();if(!text){toast('Cole um enunciado ou escreva um assunto.');$('#question').focus();return;}$('#consult').disabled=true;$('#consult-results').innerHTML='<p class="help">Pesquisando no seu material…</p>';try{const result=await api('consult',{text,mode:'statement',folderId:$('#consult-folder').value?Number($('#consult-folder').value):undefined,limit:20});const cards=result.results;$('#consult-results').innerHTML=cards.length?'<p class="help">'+cards.length+' material(is) relacionado(s). Abra para estudar o conteúdo completo.</p>'+cards.map(n=>{const passage=n.passages?.[0];return '<article class="result-card"><h4>'+icon('note')+' '+esc(n.title)+'</h4><p class="path">'+esc(n.path||'Sem pasta')+'</p>'+(passage?'<p class="snippet">'+snippetHtml(typeof passage==='string'?passage:passage.text||'',n.matchedTerms)+'</p>':'<p class="help">Correspondência no título, na pasta ou nas etiquetas.</p>')+'<button class="outline" data-result-note="'+n.id+'">'+icon('note')+' Abrir anotação</button></article>';}).join(''):'<div class="empty compact">'+icon('search')+'<p>Nenhum material relacionado encontrado.</p><small>Tente palavras do assunto ou cadastre sinônimos nas configurações.</small></div>';for(const b of $$('[data-result-note]'))b.onclick=()=>run(()=>{const r=cards.find(n=>n.id===Number(b.dataset.resultNote));return openNote(r.id,r.matchedTerms);});}finally{$('#consult').disabled=false;}}
async function globalSearch(q,folderId=searchFolder()){const seq=++state.searchSeq;await leaveEditor();if(seq!==state.searchSeq)return;searchRoute={query:q,folderId};setView('search');const result=await api('search',q,{limit:100,folderId});if(seq!==state.searchSeq)return;$('#main').innerHTML=intro('PESQUISA NO CADERNO','Resultados para “'+q+'”',(result.results.length===100?'Exibindo até 100 resultados.':result.results.length+' material(is) encontrado(s).')+' Escopo: '+(folderId==null?'Toda a biblioteca':folderPath(folderId)))+(result.results.length?result.results.map(n=>'<article class="result-card"><h3>'+esc(n.title)+'</h3><p class="path">'+esc(n.path||'Sem pasta')+'</p><p class="snippet">'+snippetHtml(n.snippet,n.matchedTerms)+'</p><button class="outline small" data-search-note="'+n.id+'">Abrir anotação</button></article>').join(''):'<div class="empty">'+icon('search')+'<p>Nenhuma anotação encontrada.</p><small>Use palavras mais curtas, outra expressão ou uma frase entre aspas.</small></div>');for(const b of $$('[data-search-note]'))b.onclick=()=>run(()=>openNote(Number(b.dataset.searchNote),result.results.find(n=>n.id===Number(b.dataset.searchNote)).matchedTerms));renderTree();}
async function settings(){await leaveEditor();setView('settings');$('#main').innerHTML=intro('SEU CADERNO, SEUS DADOS','Dados e configurações','Escolha onde guardar seus materiais e mantenha cópias de segurança.')+'<section class="settings-section"><h2>'+icon('database')+' Local de salvamento</h2><p>Todos os resumos, pastas e anexos desta biblioteca ficam neste local.</p><div class="path-box">'+esc(state.info.directory)+'</div><div class="button-row"><button id="open-data" class="outline small">Abrir pasta</button><button id="move-data" class="outline small">Copiar biblioteca para outra pasta</button><button id="switch-data" class="outline small">Abrir outra biblioteca</button></div><p class="help">Ao copiar, a biblioteca original é preservada. No pendrive, feche o programa e ejete com segurança antes de desconectar.</p></section><section class="settings-section"><h2>Importar, exportar e proteger</h2><p>O pacote completo preserva anotações, formatação, pastas, versões, temas e anexos.</p><div class="button-row"><button id="export-library" class="primary small">'+icon('export')+' Exportar biblioteca completa</button><button id="import-library" class="outline small">'+icon('import')+' Acrescentar materiais</button><button id="restore-library" class="outline small">Restaurar biblioteca</button><button id="import-text" class="outline small">Importar TXT / HTML</button></div><p class="help">Importação aceita .b9mm, .bizuteca e .tvbackup. “Acrescentar” mantém seu caderno e ignora notas idênticas; “Restaurar” substitui a biblioteca após confirmação e backup.</p></section><section class="settings-section"><h2>Consulta e sinônimos</h2><p>Relacione expressões diferentes usadas no mesmo assunto. Exemplo: “PEPS” e “primeiro que entra primeiro que sai”.</p><div class="button-row"><button id="synonyms" class="outline small">Gerenciar sinônimos</button></div></section><section class="settings-section"><h2>Leitura e navegação</h2><label class="field inline"><input id="start-last-note" type="checkbox" '+(state.prefs.startLast!==false?'checked':'')+'> Reabrir a última anotação ao iniciar</label><label class="field inline"><input id="hide-query" type="checkbox" '+(state.prefs.consultOpen===false?'checked':'')+'> Manter consulta recolhida</label><div class="button-row"><button id="appearance-settings" class="outline small">'+icon('palette')+' Aparência e temas</button></div><ul class="key-list"><li><kbd>Ctrl N</kbd> Nova anotação</li><li><kbd>Ctrl K</kbd> Pesquisar no caderno</li><li><kbd>Ctrl J</kbd> Abrir ou recolher consulta</li><li><kbd>Ctrl S</kbd> Salvar agora</li></ul><p class="help">BIZUTECA 9MM '+esc(state.info.version)+' · Funciona sem internet · Sem animações</p></section>';
 await addBackupControls();$('#open-data').onclick=()=>run(()=>api('openData'));$('#move-data').onclick=()=>run(()=>switchData('move'));$('#switch-data').onclick=()=>run(()=>switchData('open'));$('#export-library').onclick=()=>run(async()=>{const f=await api('exportLibrary');if(f)toast('Biblioteca exportada com sucesso.');});$('#import-library').onclick=()=>run(()=>importLibrary('merge'));$('#restore-library').onclick=()=>run(()=>importLibrary('replace'));$('#import-text').onclick=()=>run(async()=>{const destination=await openDialog('Importar anotações',folderPicker('folder',null),[{id:'cancel',text:'Cancelar'},{id:'ok',text:'Escolher arquivos',primary:true}]);if(destination.id!=='ok')return;const folderId=destination.values.folder?Number(destination.values.folder):null;const n=await api('importText',folderId);if(n){await refresh();if(folderId!=null)await showFolder(folderId);else await home();toast(n+' anotação(ões) importada(s).');}});$('#synonyms').onclick=()=>run(showSynonyms);$('#appearance-settings').onclick=()=>run(showThemes);$('#start-last-note').onchange=e=>{state.prefs.startLast=e.target.checked;soonPrefs();};$('#hide-query').onchange=e=>toggleConsult(!e.target.checked);}
async function reloadInfo(){state.info=await api('init');state.prefs=state.info.settings||{};state.custom=(state.info.themes||[]).map(t=>{try{return BizThemes.validate(t);}catch{return null;}}).filter(Boolean);state.theme=state.prefs.theme||'tactical';state.expanded=new Set(state.prefs.expanded||[]);applyTheme(themeById(state.theme));$('#workspace').classList.toggle('hide-consult',state.prefs.consultOpen===false);setSidebarWidth();await refresh();placeStatus();window.BizMusic.load().catch(console.error);}
async function switchData(mode){const r=await api('changeData',mode);if(r){await reloadInfo();await settings();toast('Local de dados atualizado. A biblioteca anterior foi preservada.');}}
async function importLibrary(mode){const r=await api('importLibrary',mode);if(r){await reloadInfo();await home();toast(r.restored?'Biblioteca restaurada em uma pasta separada.':r.inserted+' anotação(ões) acrescentada(s); '+r.duplicates+' duplicada(s) ignorada(s).');}}
async function showSynonyms(){const list=await api('listSynonyms');const r=await openDialog('Sinônimos da pesquisa','<div class="form-grid"><label class="field">Termo<input name="a" placeholder="Ex.: PEPS"></label><label class="field">Expressão equivalente<input name="b" placeholder="Primeiro que entra primeiro que sai"></label></div><div class="help">'+(list.length?list.map(s=>esc(s.a)+' ↔ '+esc(s.b)).join('<br>'):'Nenhum sinônimo cadastrado.')+'</div>',[{id:'remove',text:'Remover par informado'},{id:'cancel',text:'Fechar'},{id:'add',text:'Adicionar',primary:true}]);if(['add','remove'].includes(r.id)){if(!r.values.a.trim()||!r.values.b.trim())throw Error('Preencha os dois termos.');await api(r.id==='add'?'addSynonym':'removeSynonym',r.values.a,r.values.b);toast(r.id==='add'?'Sinônimo adicionado.':'Par removido.');await showSynonyms();}}
function miniTheme(t){if(t.visualUniverse)return '<div class="universe-preview universe-card-art" style="--art-fallback:'+t.bg+'"><img src="'+esc(BizThemes.backgroundSource(t))+'" alt="" loading="lazy" decoding="async" style="object-position:'+esc(t.artFocus||t.artPosition+' center')+'"></div>';return '<div class="theme-preview" style="--preview-bg:'+t.bg+';--preview-surface:'+t.surface+';--preview-text:'+t.text+';--preview-accent:'+t.accent+';--preview-round:'+t.round+';--preview-font:'+esc(t.heading)+'"><div>Biblioteca<div class="mini-line"></div><div class="mini-accent"></div><div class="mini-line"></div><div class="mini-line"></div></div><div><h4>Meu caderno</h4><div class="mini-line"></div><div class="mini-line"></div><div class="mini-accent"></div></div><div>Consulta<div class="mini-line"></div><div class="mini-accent"></div></div></div>';}
async function showThemes(category=''){await leaveEditor();setView('themes');$('#main').innerHTML=intro('APARÊNCIA','Escolha seu ambiente de estudo','36 temas clássicos e 38 universos ilustrados para usar offline.')+'<div class="theme-filters"><input id="theme-search" placeholder="Pesquisar tema" aria-label="Pesquisar tema"><select id="theme-category" aria-label="Categoria de temas"><option value="">Todas as categorias</option>'+[...BizThemes.groups,'Meus temas','Universos Visuais','Favoritos'].map(x=>'<option>'+esc(x)+'</option>').join('')+'</select></div><div class="button-row" style="margin-top:0;margin-bottom:22px"><button id="create-universe" class="outline small">Criar Universo Visual</button><button id="open-universes" class="outline small">Universos Visuais</button><button id="import-theme" class="outline small">Importar tema JSON</button><button id="default-theme" class="outline small">Restaurar padrão 9MM</button></div><div id="themes-grid" class="themes-grid"></div>';
 const render=()=>{const q=normalize($('#theme-search').value),cat=$('#theme-category').value,favs=state.prefs.favoriteThemes||[];const list=allThemes().filter(t=>(!q||normalize(t.name+' '+t.description).includes(q))&&(!cat||(cat==='Favoritos'?favs.includes(t.id):t.category===cat)));$('#themes-grid').innerHTML=list.map(t=>'<article class="theme-card '+(state.theme===t.id?'chosen':'')+'">'+miniTheme(t)+'<div class="theme-info"><span class="theme-category">'+esc(t.category)+(state.theme===t.id?' · EM USO':'')+'</span><h3>'+esc(t.name)+'<button class="theme-star" data-theme-fav="'+t.id+'" aria-label="Favoritar tema">'+icon(favs.includes(t.id)?'star-filled':'star')+'</button></h3><p>'+esc(t.description||'Seu tema personalizado')+'</p><div class="theme-actions"><button data-theme-apply="'+t.id+'" class="primary">Aplicar</button><button data-theme-preview="'+t.id+'" class="outline">'+(t.visualUniverse?'Prévia e transparência':'Prévia')+'</button><button data-theme-edit="'+t.id+'" class="outline">Personalizar</button>'+(t.custom?'<button data-theme-manage="'+t.id+'" class="outline">Opções</button>':'')+'</div></div></article>').join('');for(const b of $$('[data-theme-apply]'))b.onclick=()=>run(()=>chooseTheme(b.dataset.themeApply));for(const b of $$('[data-theme-preview]'))b.onclick=()=>previewTheme(b.dataset.themePreview);for(const b of $$('[data-theme-edit]'))b.onclick=()=>run(()=>customizeTheme(b.dataset.themeEdit));for(const b of $$('[data-theme-manage]'))b.onclick=()=>run(()=>manageTheme(b.dataset.themeManage));for(const b of $$('[data-theme-fav]'))b.onclick=()=>{const id=b.dataset.themeFav;state.prefs.favoriteThemes=favs.includes(id)?favs.filter(v=>v!==id):[...favs,id];soonPrefs();render();};};$('#theme-category').value=category;$('#open-universes').onclick=()=>{$('#theme-category').value='Universos Visuais';$('#theme-search').value='';render();};$('#create-universe').onclick=()=>run(createUniverse);$('#theme-search').oninput=render;$('#theme-category').onchange=render;$('#default-theme').onclick=()=>run(()=>chooseTheme('tactical'));$('#import-theme').onclick=()=>run(async()=>{const raw=await api('importTheme');if(!raw)return;const t=BizThemes.validate({...raw,id:'custom-'+crypto.randomUUID(),custom:true});state.custom.push(t);await api('saveThemes',state.custom);await showThemes();toast('Tema importado.');});render();}
async function chooseTheme(id,appearance){
 if(appearance)state.prefs.universeAppearance={...state.prefs.universeAppearance,[id]:appearance};
 state.theme=id;
 applyTheme(themeById(id));
 $('.preview-banner')?.remove();
 await savePrefs();
 if(state.view==='themes')await showThemes(appearance?'Universos Visuais':'');
 toast('Tema aplicado. Seus materiais foram preservados.');
}
function previewTheme(id){
 const theme=themeById(id);
 const appearance=universeAppearance(id);
 applyTheme(theme);
 $('.preview-banner')?.remove();
 const banner=document.createElement('div');
 banner.className='preview-banner';
 banner.setAttribute('role','region');
 banner.setAttribute('aria-label','Prévia do tema');
 const slider=(key,label)=>'<label class="universe-slider" for="universe-'+key+'"><span>'+label+'</span><input id="universe-'+key+'" type="range" min="0" max="100" value="'+appearance[key]+'"><output for="universe-'+key+'">'+appearance[key]+'%</output></label>';
 banner.innerHTML='<strong>Prévia: '+esc(theme.name)+'</strong>'+
   (theme.visualUniverse?'<div class="universe-sliders">'+slider('wallpaper','Visibilidade da imagem')+slider('interface','Transparência da interface')+'</div>':'')+
   '<div class="preview-actions"><button class="primary small" id="accept-preview">Aplicar</button><button class="outline small" id="cancel-preview">Voltar</button></div>';
 document.body.append(banner);
 for(const key of ['wallpaper','interface']){
   const input=banner.querySelector('#universe-'+key);
   if(!input)continue;
   input.oninput=()=>{
     appearance[key]=Number(input.value);
     input.nextElementSibling.value=input.value+'%';
     applyUniverseAppearance(appearance);
   };
 }
 $('#accept-preview').onclick=()=>run(()=>chooseTheme(id,theme.visualUniverse?appearance:undefined));
 $('#cancel-preview').onclick=()=>{applyTheme(themeById(state.theme));banner.remove();};
 (banner.querySelector('input')||$('#accept-preview')).focus();
}
async function createUniverse(){
  const background=await api('chooseBackground');
  if(!background)return;
  const r=await openDialog('Criar Universo Visual',
    '<div class="universe-preview" style="background-image:url(&quot;'+esc(background)+'&quot;)"></div>'+
    '<label class="field">Nome inspirado na cena<input name="name" required maxlength="70"></label>'+
    '<label class="field">Posição do destaque<select name="artPosition"><option value="right">Direita</option><option value="center">Centro</option><option value="left">Esquerda</option></select></label>',
    [{id:'cancel',text:'Cancelar'},{id:'save',text:'Salvar universo',primary:true}]);
  if(r.id!=='save')return;
  const base=themeById('tactical');
  const theme=BizThemes.validate({...base,id:'custom-'+crypto.randomUUID(),base:base.id,custom:true,
    visualUniverse:true,background,name:r.values.name,artPosition:r.values.artPosition,
    description:'Arte integrada à Home e ao editor'});
  const next=[...state.custom,theme];
  await api('saveThemes',next);
  state.custom=next;
  await showThemes('Universos Visuais');
}
async function customizeTheme(id){const base=themeById(id);let t={...base,id:'custom-'+crypto.randomUUID(),base:base.id,custom:true,category:'Meus temas',name:base.name+' — Meu tema'};let background=t.background,bundledArt=t.bundledArt;const colors=[['accent','Destaque principal'],['secondary','Destaque secundário'],['bg','Fundo da aplicação'],['surface','Cartões e campos'],['sidebar','Barra lateral'],['editor','Área de escrita'],['text','Texto'],['border','Bordas']];const body='<label class="field">Nome do tema<input name="name" value="'+esc(t.name)+'" maxlength="70"></label><div class="form-grid">'+colors.map(([key,label])=>'<label class="field inline">'+esc(label)+'<input type="color" name="'+key+'" value="'+t[key]+'"></label>').join('')+'<label class="field">Fonte<select name="font">'+['Segoe UI','Georgia','Consolas','Trebuchet MS','Arial','Verdana'].map(f=>'<option '+(f===t.font?'selected':'')+'>'+f+'</option>').join('')+'</select></label><label class="field">Fonte dos títulos<select name="heading">'+['Segoe UI','Georgia','Consolas','Trebuchet MS'].map(f=>'<option '+(f===t.heading?'selected':'')+'>'+f+'</option>').join('')+'</select></label><label class="field">Tamanho da interface<input name="fontSize" type="number" min="12" max="20" value="'+t.fontSize+'"></label><label class="field">Arredondamento (0–28)<input name="round" type="number" min="0" max="28" value="'+parseInt(t.round)+'"></label><label class="field">Sombras<select name="shadow">'+['none','soft','medium'].map((s,i)=>'<option value="'+s+'" '+(s===t.shadow?'selected':'')+'>'+['Sem sombra','Suaves','Médias'][i]+'</option>').join('')+'</select></label><label class="field">Decoração (0–35%)<input name="decoration" type="number" min="0" max="35" value="'+Math.round(t.decoration*100)+'"></label><label class="field">Botões<select name="buttonStyle"><option value="flat">Planos</option><option value="raised" '+(t.buttonStyle==='raised'?'selected':'')+'>Com relevo</option></select></label><label class="field">Ícones<select name="iconStyle"><option value="line">Simples</option><option value="badge" '+(t.iconStyle==='badge'?'selected':'')+'>Com fundo</option></select></label></div><button id="background-pick" class="outline small">Escolher imagem de fundo</button> <button id="background-remove" class="outline small">Remover imagem</button><p id="background-label" class="help">'+(background?'Imagem personalizada selecionada.':bundledArt?'Arte da coleção selecionada.':'Sem imagem personalizada.')+'</p><p class="help">A imagem fica atrás da interface; a área de escrita permanece sólida para leitura. O contraste do texto é verificado antes de salvar.</p><div id="theme-form-error" class="form-error"></div>';
 const promise=openDialog('Criar tema a partir de '+base.name,body,[{id:'cancel',text:'Cancelar'},{id:'save',text:'Salvar tema',primary:true}]);$('#background-pick').onclick=()=>run(async()=>{const img=await api('chooseBackground');if(img){background=img;$('#background-label').textContent='Imagem personalizada selecionada.';}});$('#background-remove').onclick=()=>{background='';bundledArt='';$('#background-label').textContent='Sem imagem personalizada.';};const r=await promise;if(r.id==='save'){t={...t,...r.values,background,bundledArt,decoration:Number(r.values.decoration)/100,round:r.values.round+'px'};t.ink=BizThemes.contrast(t.accent,'#08120c')>BizThemes.contrast(t.accent,'#ffffff')?'#08120c':'#ffffff';t.muted=BizThemes.mix(t.text,t.surface,.22);try{t=BizThemes.validate(t);}catch(e){toast(e.message,true);return;}state.custom.push(t);await api('saveThemes',state.custom);await chooseTheme(t.id);}}
async function manageTheme(id){const t=themeById(id);const r=await openDialog(t.name,'<label class="field">Nome<input name="name" value="'+esc(t.name)+'" maxlength="70"></label>',[{id:'delete',text:'Excluir',danger:true},{id:'duplicate',text:'Duplicar'},{id:'export',text:'Exportar JSON'},{id:'rename',text:'Renomear',primary:true},{id:'cancel',text:'Fechar'}]);if(r.id==='cancel')return;if(r.id==='export'){const p=await api('exportTheme',t);if(p)toast('Tema exportado.');return;}if(r.id==='delete'){if(!await confirmAction('Excluir tema personalizado?','Suas anotações permanecerão intactas.'))return;state.custom=state.custom.filter(x=>x.id!==id);if(state.theme===id)state.theme='tactical';}if(r.id==='duplicate')state.custom.push({...t,id:'custom-'+crypto.randomUUID(),name:t.name+' — Cópia'});if(r.id==='rename'){const name=r.values.name.trim();if(!name)throw Error('Informe um nome.');state.custom.find(x=>x.id===id).name=name;}await api('saveThemes',state.custom);applyTheme(themeById(state.theme));await savePrefs();await showThemes();}
async function navigate(view){await flush();$('.preview-banner')?.remove();applyTheme(themeById(state.theme));if(view==='calendar')return calendar();if(view==='trash')return trash();if(view==='settings')return settings();if(view==='themes')return showThemes();return home(view);}
$('#home').onclick=()=>run(()=>navigate('home'));$('#new-note').onclick=()=>run(()=>newNote());$('#new-folder').onclick=()=>run(()=>newFolder());$('#toggle-consult').onclick=()=>toggleConsult();$('#close-consult').onclick=()=>toggleConsult(false);$('#consult').onclick=()=>run(doConsult);$('#question').onkeydown=e=>{if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();run(doConsult);}};$('#clear-consult').onclick=()=>{$('#question').value='';$('#consult-results').innerHTML='<div class="empty compact"><p>Cole uma questão para localizar seu material.</p></div>';};$('#toggle-library').onclick=()=>{$('#workspace').classList.toggle('hide-library');};let treeFrame;$('#tree-search').oninput=()=>{cancelAnimationFrame(treeFrame);treeFrame=requestAnimationFrame(renderTree);};$('#collapse-all').onclick=()=>{state.expanded.clear();renderTree();soonPrefs();};for(const b of $$('.side-nav button'))b.onclick=()=>run(()=>navigate(b.dataset.view));$('#data-status').onclick=()=>run(()=>navigate('settings'));$('#backup').onclick=()=>run(async()=>{await flush();const file=await api('backup');toast('Backup criado: '+file);});let searchTimer;$('#global-search').oninput=e=>{clearTimeout(searchTimer);const q=e.target.value.trim();if(q)searchTimer=setTimeout(()=>run(()=>globalSearch(q)),350);};$('#global-search').onkeydown=e=>{if(e.key==='Enter'){clearTimeout(searchTimer);const q=e.target.value.trim();if(q)run(()=>globalSearch(q));}if(e.key==='Escape')e.target.value='';};
$('#resize-library').onpointerdown=e=>{e.preventDefault();const move=ev=>{state.prefs.sideWidth=setSidebarWidth(ev.clientX);};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);document.removeEventListener('pointercancel',up);soonPrefs();};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);document.addEventListener('pointercancel',up,{once:true});};
document.addEventListener('keydown',e=>{if(e.ctrlKey&&!e.altKey){const k=e.key.toLowerCase();if(k==='s'){e.preventDefault();run(flush);}if(k==='n'){e.preventDefault();if(!$('#dialog').open)run(()=>newNote());}if(k==='k'){e.preventDefault();$('#global-search').focus();$('#global-search').select();}if(k==='j'){e.preventDefault();toggleConsult();}}});
window.biz.onClose(async()=>{try{await flushStable();await savePrefs();window.biz.readyToClose();}catch(e){toast('Não foi possível salvar. Reconecte o dispositivo e pressione Ctrl S antes de fechar.',true);}});
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'Não foi possível concluir a operação.',true);console.error(e.reason);});
wireUpgrades();window.biz.onBackupWarning(message=>toast(message,true));
run(async()=>{try{await reloadInfo();if(state.prefs.startLast!==false&&state.prefs.lastNote&&state.notes.some(n=>n.id===state.prefs.lastNote))await openNote(state.prefs.lastNote);else await home();window.biz.readyToShow(true);}catch(error){window.biz.readyToShow(false);throw error;}});
